import json, os
from pathlib import Path
from datetime import datetime, timezone, timedelta
TZ=timezone(timedelta(hours=8))
day="2026-09-15"

# find jsonl transcripts modified today under all projects
roots=[
 Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode/agent-transcripts'),
 Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode-omdb/agent-transcripts'),
 Path('/Users/mac/.cursor/projects/Users-mac-Desktop-CHcode-omdb-tgbot/agent-transcripts'),
]
cands=[]
for root in roots:
  if not root.exists(): continue
  for p in root.rglob('*.jsonl'):
    m=datetime.fromtimestamp(p.stat().st_mtime, tz=TZ)
    if m.strftime('%Y-%m-%d')==day:
      cands.append((m,p))
cands.sort(reverse=True)
print('today transcripts', len(cands))
for m,p in cands[:50]:
  # extract first user message briefly
  first=''; last=''
  try:
    with open(p,encoding='utf-8',errors='replace') as f:
      for line in f:
        try:o=json.loads(line)
        except: continue
        role=o.get('role') or (o.get('message') or {}).get('role') if isinstance(o.get('message'),dict) else o.get('type')
        # cursor format often {"role":"user","message":{"content":[...]}}
        msg=o.get('message') or o
        content=msg.get('content') if isinstance(msg,dict) else None
        text=''
        if isinstance(content,str): text=content
        elif isinstance(content,list):
          parts=[]
          for x in content:
            if isinstance(x,dict):
              if x.get('type')=='text': parts.append(x.get('text') or '')
              elif 'text' in x: parts.append(str(x.get('text')))
            elif isinstance(x,str): parts.append(x)
          text=' '.join(parts)
        text=' '.join(text.split())
        if role=='user' and text:
          if not first: first=text[:200]
          last=text[:200]
  except Exception as e:
    first=f'ERR {e}'
  print(f"\n{m.strftime('%H:%M')} {p.parent.name[:8]}…")
  print('  F:', first[:180])
  print('  L:', last[:180])
